// Disposable QA client only. No elevation or policy edits. Invoked as a newly
// created local Users-only account, never as the runner administrator.
using System;using System.IO;using System.Diagnostics;using System.Security.Principal;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Runtime.InteropServices;
static class OrdinaryUninstallProbe {
 static object Policy(string hive,string subkey,string name){using(var key=(hive=="machine"?Microsoft.Win32.Registry.LocalMachine:Microsoft.Win32.Registry.CurrentUser).OpenSubKey(subkey))return key==null?null:key.GetValue(name,null);}
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool GetTokenInformation(IntPtr token,int kind,IntPtr value,int length,out int needed);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
 static int TokenInt(IntPtr token,int kind){int size;GetTokenInformation(token,kind,IntPtr.Zero,0,out size);if(size<4||size>65536)throw new Exception("OUQ_TOKEN_SIZE");var p=Marshal.AllocHGlobal(size);try{if(!GetTokenInformation(token,kind,p,size,out size))throw new Exception("OUQ_TOKEN_QUERY");return kind==25?int.Parse(new SecurityIdentifier(Marshal.ReadIntPtr(p)).Value.Substring(7)):Marshal.ReadInt32(p);}finally{Marshal.FreeHGlobal(p);}}
 static object Call(string exe,string args){using(var p=new Process{StartInfo=new ProcessStartInfo{FileName=exe,Arguments=args,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){p.Start();var o=p.StandardOutput.ReadToEndAsync();var e=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(150000)){p.Kill();throw new Exception("OUQ_CHILD_TIMEOUT");}if(o.Result.Length>65536||e.Result.Length>65536)throw new Exception("OUQ_OUTPUT_OVERFLOW");return new{exitCode=p.ExitCode,stdout=o.Result,stderr=e.Result};}}
 public static int Main(string[] args){try{if(args.Length!=1||!System.Text.RegularExpressions.Regex.IsMatch(args[0],@"\A\{[A-Fa-f0-9-]{36}\}\z"))throw new Exception("OUQ_GUID_REQUIRED");string root=AppDomain.CurrentDomain.BaseDirectory,output=Path.Combine(root,"result");var id=WindowsIdentity.GetCurrent();IntPtr token;if(!OpenProcessToken(Process.GetCurrentProcess().Handle,8,out token))throw new Exception("OUQ_TOKEN_OPEN");int il,elevated;try{il=TokenInt(token,25);elevated=TokenInt(token,20);}finally{CloseHandle(token);}bool admin=new WindowsPrincipal(id).IsInRole(WindowsBuiltInRole.Administrator);if(admin||elevated!=0||il!=8192)throw new Exception("OUQ_ORDINARY_TOKEN_REQUIRED");
 var facts=new Dictionary<string,object>{{"sid",id.User.Value},{"integrityRid",il},{"elevated",false},{"administrator",false},{"pid",Process.GetCurrentProcess().Id},{"controlPanelUiTested",false},{"uacPromptTested",false}};
 facts["machineAlwaysInstallElevated"]=Policy("machine",@"SOFTWARE\Policies\Microsoft\Windows\Installer","AlwaysInstallElevated");facts["userAlwaysInstallElevated"]=Policy("user",@"SOFTWARE\Policies\Microsoft\Windows\Installer","AlwaysInstallElevated");facts["enableLUA"]=Policy("machine",@"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System","EnableLUA");if(Convert.ToInt32(facts["machineAlwaysInstallElevated"])==1||Convert.ToInt32(facts["userAlwaysInstallElevated"])==1)throw new Exception("OUQ_UNSAFE_INSTALL_POLICY");
 string bridge=Path.Combine(root,"AgentoC.ManagedOwnerMsiBridge.exe");facts["removeCheck"]=Call(bridge,"remove-check");facts["directRemove"]=Call(bridge,"remove");facts["admission"]=Call(bridge,"remove-admission");
 facts["msi"]=Call(@"C:\Windows\System32\msiexec.exe","/x "+args[0]+" /qn /norestart /l*v \""+Path.Combine(output,"ordinary-msi.log")+"\"");
 File.WriteAllText(Path.Combine(output,"ordinary-client.json"),new JavaScriptSerializer().Serialize(facts));return 0;
 }catch{Console.Error.WriteLine("OUQ_CLIENT_FAILED");return 1;}}
}
